<?php require '../config/database.php';require '../config/auth.php';require_role('student');$q=$pdo->prepare('SELECT * FROM students WHERE id=?');$q->execute([$_SESSION['student_id']]);$s=$q->fetch();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('UPDATE students SET name=?,email=?,phone=? WHERE id=?');$q->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),$s['id']]);$q=$pdo->prepare('UPDATE users SET name=? WHERE student_id=?');$q->execute([trim($_POST['name']),$s['id']]);$_SESSION['name']=trim($_POST['name']);$msg='Profile updated successfully.';$q=$pdo->prepare('SELECT * FROM students WHERE id=?');$q->execute([$s['id']]);$s=$q->fetch();}$page_title='My Profile';require '../includes/header.php';?><h1>My Profile</h1><p class="muted">Edit your profile details.</p><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><div class="card"><form method="post"><div class="form"><label>Name</label><input name="name" value="<?=htmlspecialchars($s['name'])?>" required></div><div class="form"><label>Email</label><input type="email" name="email" value="<?=htmlspecialchars($s['email'])?>" required></div><div class="form"><label>Phone</label><input name="phone" value="<?=htmlspecialchars($s['phone'])?>"></div><button class="btn">Save Changes</button></form></div><?php require '../includes/footer.php';?>
